{
  "findings": [
    {
      "check_id": "CKV_AWS_23",
      "title": "Security group ingress allows access from all IPs (0.0.0.0/0)",
      "resource": "aws_security_group.vault",
      "severity": "HIGH",
      "explanation": "The dynamic ingress block explicitly sets cidr_blocks to ["0.0.0.0/0"], allowing unrestricted internet access to the specified ports on the Vault security group, which significantly increases the attack surface."
    }
  ],
  "patched_code": "resource "aws_security_group" "vault" {
  name        = "vault"
  description = "Ingress for Vault"
  vpc_id      = aws_vpc.my_vpc.id
  dynamic "ingress" {
    iterator = port
    for_each = var.ingress_ports
    content {
      from_port   = port.value
      to_port     = port.value
      protocol    = "tcp"
      # TODO: Replace with specific CIDR blocks or security group IDs to restrict access
      cidr_blocks = []
    }
  }
}",
  "fix_summary": "Removed the hardcoded '0.0.0.0/0' CIDR block from the dynamic ingress configuration and replaced it with an empty list to prevent open access by default. Added a comment indicating that specific, restricted CIDR blocks should be provided via variables or explicit configuration."
}
